describe("doctests of sympy.series.limits", () => {
  it("Limit(sin(x)/x, x, 0)", () => {
    const x = new Sym('x');
    expect(sympyStr(new Limit([mul(pow(x, -1), fn('sin', [x])), x, rational(0)], '+'))).toBe('Limit(sin(x)/x, x, 0, dir=\'+\')');
  });
  it("Limit(1/x, x, 0, dir=\"-\")", () => {
    const x = new Sym('x');
    expect(sympyStr(new Limit([pow(x, -1), x, rational(0)], '-'))).toBe('Limit(1/x, x, 0, dir=\'-\')');
  });
  it("limit(sin(x)/x, x, 0)", () => {
    const x = new Sym('x');
    expect(sympyStr(limit(mul(pow(x, -1), fn('sin', [x])), x, rational(0), '+'))).toBe('1');
  });
  it("limit(1/x, x, 0) # default dir='+'", () => {
    const x = new Sym('x');
    expect(sympyStr(limit(pow(x, -1), x, rational(0), '+'))).toBe('oo');
  });
  it("limit(1/x, x, 0, dir=\"-\")", () => {
    const x = new Sym('x');
    expect(sympyStr(limit(pow(x, -1), x, rational(0), '-'))).toBe('-oo');
  });
  it("limit(1/x, x, 0, dir='+-')", () => {
    const x = new Sym('x');
    expect(sympyStr(limit(pow(x, -1), x, rational(0), '+-'))).toBe('zoo');
  });
  it("limit(1/x, x, oo)", () => {
    const x = new Sym('x');
    expect(sympyStr(limit(pow(x, -1), x, oo, '+'))).toBe('0');
  });
});

